75	/// Test-friendly variant: validate against an arbitrary root list.
76	fn validate_against(user_path: &str, roots: &[PathBuf]) -> Result<ValidatedPath> {
77	    if user_path.is_empty() {
78	        bail!("path is empty");
79	    }
80	    if user_path.len() > MAX_PATH_LEN {
81	        bail!("path exceeds PATH_MAX ({} bytes)", MAX_PATH_LEN);
82	    }
83	    if user_path.contains('\0') {
84	        bail!("path contains NUL byte");
85	    }
86	    if user_path.contains('%') {
87	        bail!("percent-encoded characters not allowed");
88	    }
89	    if user_path.contains('\\') {
90	        bail!("backslash characters not allowed");
91	    }
92	
93	    let p = Path::new(user_path);
94	    if !p.is_absolute() {
95	        bail!("path must be absolute (starts with /)");
96	    }
97	
98	    // Pick the longest matching whitelist root so e.g. /var/log wins over /
99	    // (if / were ever whitelisted) for paths like /var/log/syslog.
100	    let mut best: Option<&PathBuf> = None;
101	    for root in roots {
102	        if p.starts_with(root) {
103	            match best {
104	                None => best = Some(root),
105	                Some(b) if root.as_os_str().len() > b.as_os_str().len() => best = Some(root),
106	                _ => {}
107	            }
108	        }
109	    }
110	    let root = best.ok_or_else(|| {
111	        anyhow!("'{}' is not under any whitelisted root", user_path)
112	    })?;
113	
114	    let rel = p.strip_prefix(root)
115	        .map_err(|_| anyhow!("internal: strip_prefix failed"))?;
116	    let rel_str = if rel.as_os_str().is_empty() {
117	        ".".to_string()
118	    } else {
119	        rel.to_string_lossy().into_owned()
120	    };
121	
122	    Ok(ValidatedPath { root: root.clone(), rel: rel_str })
123	}
