816	            let ch = match r {
817	                0..=4   => '\0',
818	                5..=12  => '%',
819	                13..=20 => '\\',
820	                21..=32 => '.',
821	                33..=44 => '/',
822	                45..=49 => '~',
823	                50..=59 => 'a',
824	                60..=69 => 'b',
825	                70..=79 => '1',
826	                80..=89 => '-',
827	                _       => '_',
828	            };
829	            s.push(ch);
